function menuDrawDrafts(panel){panel.append(menuNode('h2',mt('drafts')));if(!menuUi.drafts.length){panel.append(menuNode('p',mt('noDrafts'),'menu-empty'));return;}for(const saved of menuUi.drafts){const row=menuNode('div',undefined,'menu-draft-row');row.append(menuNode('strong',`#${saved.revision} · ${new Date(saved.updatedAt).toLocaleString(lang==='ky'?'ky-KG':'ru-RU')}`),menuNode('small',`${mt('current')}: #${saved.baseRevision}`));menuButton(row,mt('chooseDraft'),async()=>{if(!await menuMayLeave())return;const loaded=await api('draftGet',{id:saved.id});menuState={...loaded.catalog,baseRevision:loaded.baseRevision};draft={draftId:loaded.id,draftRevision:loaded.revision};dirty=false;menuUi.form=null;menuUi.item=null;menuUi.category='all';menuUi.view='catalog';if(serverSchema>=12){await api('menuSyncLease',{active:true,draftId:saved.id});menuSyncLeaseHeld=true;}menuDraw();});if(serverSchema>=12)menuButton(row,lang==='ky'?'Өзгөртүүнү бүтүрүү':'Завершить редактирование',async()=>{if(!await confirmAction(lang==='ky'?'Каралама сакталат, бирок авто-жаңыртууну кармабайт.':'Черновик останется в истории, но перестанет удерживать автоматическое обновление меню. Продолжить?'))return;await api('menuSyncFinishDraft',{draftId:saved.id});message(lang==='ky'?'Каралама жабылды':'Редактирование черновика завершено');});panel.append(row);}}
