async function menuRevisionPreview(revision){const dialog=el('dialog',undefined,{className:'menu-dialog menu-revision-preview'});dialog.append(menuNode('h2',`${mt('history')} · #${revision}`),menuNode('p',mt('working')));document.body.append(dialog);dialog.onclose=()=>dialog.remove();dialog.showModal();let result;try{result=await api('menuRevisionGet',{revision});}catch(error){dialog.replaceChildren(menuNode('h2',mt('history')),menuNode('p',mt('historyFailed'),'menu-field-error'));throw error;}if(!dialog.open)return;dialog.replaceChildren(menuNode('h2',`${mt('history')} · #${result.revision}`),menuNode('p',`${menuDate(result.createdAt)} · ${result.authorName} · ${mt('readOnly')}`));for(const category of result.catalog.categories){const block=menuNode('section',undefined,'menu-history-category');block.append(menuNode('h3',category.name+(category.archived?' · '+mt('archive'):'')));for(const item of result.catalog.items.filter(i=>i.categoryId===category.id)){const product=menuNode('div',undefined,'menu-history-product');product.append(menuNode('strong',item.name+(item.archived?' · '+mt('archive'):'')));if(item.kind==='SET'){product.append(menuNode('p',menuMoney(item.price)));for(const c of item.components??[]){const child=result.catalog.items.find(i=>i.id===c.itemId);product.append(menuNode('p',`${c.quantity} × ${child?.name??c.itemId} · ${child?orderSelectionLabel(child,c):''}`));}}else if(item.pricingMode==='MATRIX')for(const row of item.combinationPrices)product.append(menuNode('p',`${menuMatrixLabel(item,row)} — ${menuMoney(row.price)}`));else if(item.variants.length)for(const variant of item.variants)product.append(menuNode('p',`${variant.name} — ${menuMoney(variant.price)}`));else product.append(menuNode('p',menuMoney(item.price)));block.append(product);}dialog.append(block);}}
function menuReadEditor(panel,item){const content=menuNode('div',undefined,'menu-editor-content');content.append(menuNode('p',mt('readOnly'),'muted'),menuNode('p',item.description??''),menuNode('strong',menuPrice(item)));if(item.kind==='SET')menuSetContents(content,item,true);else if(item.pricingMode==='MATRIX')menuMatrixRows(content,item,true);else{for(const variant of item.variants)content.append(menuNode('p',`${variant.name} · ${menuMoney(variant.price)}`));for(const group of item.groups)content.append(menuNode('p',`${group.name}: ${group.options.map(o=>`${o.name} +${menuMoney(o.price)}`).join(', ')}`));}panel.append(content);}
function menuCategoryDialog(category){const value=category?menuClone(category):{id:crypto.randomUUID(),name:'',archived:false,translations:{}};const dialog=el('dialog',undefined,{className:'menu-dialog'});dialog.append(menuNode('h2',category?mt('editCategory'):mt('createCategory')));menuInput(dialog,t('name'),value.name,text=>{value.name=text;},{required:true});for(const code of menuState.languages.filter(code=>code!==menuState.mainLanguage)){menuInput(dialog,`${code.toUpperCase()} · ${t('name')}`,value.translations?.[code]??'',text=>{value.translations??={};if(text.trim())value.translations[code]=text;else delete value.translations[code];});}const original=JSON.stringify(value);POSDialogs.guard(dialog,()=>JSON.stringify(value)===original||confirmAction(t('discardLine')));const footer=menuNode('div',undefined,'menu-inline');dialog.append(footer);menuButton(footer,t('cancel'),()=>POSDialogs.dismiss(dialog));menuButton(footer,lang==='ky'?'Категорияны сактоо':'Сохранить категорию',()=>{if(!value.name.trim()){message(mt('invalid'));return;}if(category)Object.assign(category,value);else{menuState.categories.push(value);menuUi.category=value.id;}menuChanged();dialog.close();menuDraw();},'primary');document.body.append(dialog);dialog.onclose=()=>dialog.remove();dialog.showModal();}
async function menuArchiveCategory(category){if(!category.archived&&menuState.items.some(i=>i.categoryId===category.id&&!i.archived)){message(mt('categoryHasItems'));return;}if(!await confirmAction(category.archived?mt('restore')+'?':mt('categoryArchiveConfirm')))return;category.archived=!category.archived;menuUi.category='all';menuChanged();menuDraw();}
function menuLanguagesDialog(){const dialog=el('dialog',undefined,{className:'menu-dialog'});dialog.append(menuNode('h2',mt('languageSettings')));const main=menuInput(dialog,t('mainLanguage'),menuState.mainLanguage,()=>{}),languages=menuInput(dialog,t('languages'),menuState.languages.join(', '),()=>{});POSDialogs.guard(dialog,()=>main.value===menuState.mainLanguage&&languages.value===menuState.languages.join(', ')||confirmAction(t('discardLine')));const footer=menuNode('div',undefined,'menu-inline');dialog.append(footer);menuButton(footer,t('cancel'),()=>POSDialogs.dismiss(dialog));menuButton(footer,t('saveDraft'),()=>{const codes=languages.value.split(',').map(s=>s.trim()).filter(Boolean);if(!/^[a-z]{2,3}(?:-[A-Z]{2})?$/.test(main.value)||codes.length>30||new Set(codes).size!==codes.length||!codes.includes(main.value)||codes.some(code=>!/^[a-z]{2,3}(?:-[A-Z]{2})?$/.test(code))){message(mt('invalid'));return;}menuState.mainLanguage=main.value;menuState.languages=codes;for(const entity of [...menuState.categories,...menuState.items,...menuState.items.flatMap(i=>[...i.variants,...i.groups,...i.groups.flatMap(g=>g.options),...(i.combinationPrices??[])])])for(const code of Object.keys(entity.translations??{}))if(!codes.includes(code))delete entity.translations[code];for(const item of menuState.items)for(const code of Object.keys(item.descriptionTranslations??{}))if(!codes.includes(code)||code===main.value)delete item.descriptionTranslations[code];menuChanged();dialog.close();menuDraw();},'primary');document.body.append(dialog);dialog.onclose=()=>dialog.remove();dialog.showModal();}

function menuSetComponentError(set,c){
 const child=menuState.items.find(i=>i.id===c.itemId);
 if(!child||child.id===set.id||child.kind==='SET'||child.isPackaging||child.archived||!Number.isInteger(c.quantity)||c.quantity<1||c.quantity>99)return mt('setInvalid');
 if(child.variants.length?!child.variants.some(v=>v.id===c.variantId):c.variantId!==null)return mt('setSelection');
 const options=child.groups.flatMap(g=>g.options).filter(o=>c.modifierIds.includes(o.id));
 if(new Set(c.modifierIds).size!==c.modifierIds.length||options.length!==c.modifierIds.length||child.groups.some(g=>{const n=g.options.filter(o=>c.modifierIds.includes(o.id)).length;return n<g.min||n>g.max;}))return mt('setSelection');
 if(child.pricingMode==='MATRIX'&&!child.combinationPrices?.some(r=>r.id===c.combinationId&&r.variantId===c.variantId&&r.optionIds.length===c.modifierIds.length&&r.optionIds.every(id=>c.modifierIds.includes(id))))return mt('setSelection');
 return null;
}
function menuSetContents(parent,item,readOnly=false){
 parent.append(menuNode('h3',mt('setContents')),menuNode('p',mt('setFixed'),'muted'));if(!item.components?.length)parent.append(menuNode('p',mt('setEmpty'),'menu-empty'));
 for(const c of item.components??[]){const child=menuState.items.find(i=>i.id===c.itemId),box=menuNode('section',undefined,'menu-edit-row menu-set-component');box.append(menuNode('strong',`${c.quantity} × ${child?.name??c.itemId}`),menuNode('p',child?orderSelectionLabel(child,c):mt('setInvalid'),'muted'));const error=menuSetComponentError(item,c);if(error)box.append(menuNode('p',error,'menu-field-error'));if(!readOnly){const actions=menuNode('div',undefined,'menu-inline');menuButton(actions,t('edit'),()=>menuSetComponentDialog(item,c),'menu-quiet');menuButton(actions,mt('remove'),async()=>{if(!await confirmAction(mt('remove')+'?'))return;item.components=item.components.filter(row=>row!==c);menuMarkForm();menuDrawEditor();},'menu-quiet');box.append(actions);}parent.append(box);}
 if(!readOnly){const add=menuButton(parent,'＋ '+mt('addSetComponent'),()=>menuSetComponentDialog(item),'menu-add');add.disabled=(item.components?.length??0)>=30;parent.append(menuNode('p',mt('setLimit'),'muted'));}
}
function menuSetComponentDialog(set,existing){
 const dialog=el('dialog',undefined,{className:'menu-dialog menu-set-dialog'}),value=existing?menuClone(existing):{itemId:'',variantId:null,modifierIds:[],quantity:1},original=JSON.stringify(value);
 dialog.append(menuNode('h2',mt('addSetComponent')));const candidates=menuState.items.filter(i=>i.id!==set.id&&!i.archived&&i.kind!=='SET'&&!i.isPackaging&&!menuValidateItem(i));
 const search=menuInput(dialog,mt('search'),'',()=>drawOptions()),picker=menuSelect(dialog,mt('selectSetItem'),[['',mt('selectSetItem')],...candidates.map(i=>[i.id,i.name])],value.itemId,id=>{value.itemId=id;value.variantId=null;value.modifierIds=[];delete value.combinationId;drawSelection();}),content=menuNode('div');dialog.append(content);
 function drawOptions(){const chosen=picker.value,q=search.value.trim().toLocaleLowerCase();picker.replaceChildren(el('option',mt('selectSetItem'),{value:''}));for(const child of candidates.filter(i=>i.id===chosen||i.name.toLocaleLowerCase().includes(q)))picker.append(el('option',child.name,{value:child.id}));picker.value=chosen;}
 function drawSelection(){content.replaceChildren();const child=candidates.find(i=>i.id===value.itemId);if(!child)return;
  if(child.variants.length){const select=menuSelect(content,t('variant'),[['',mt('setSelection')],...child.variants.map(v=>[v.id,v.name])],value.variantId??'',id=>{value.variantId=id||null;});select.required=true;}
  for(const group of child.groups){if(child.pricingMode==='MATRIX'){const select=menuSelect(content,group.name,[['',mt('setSelection')],...group.options.map(o=>[o.id,o.name])],group.options.find(o=>value.modifierIds.includes(o.id))?.id??'',id=>{value.modifierIds=value.modifierIds.filter(id=>!group.options.some(o=>o.id===id));if(id)value.modifierIds.push(id);});select.required=true;}else{const fieldset=menuNode('fieldset');fieldset.append(menuNode('legend',`${group.name} (${group.min}–${group.max})`));for(const option of group.options)menuCheck(fieldset,option.name,value.modifierIds.includes(option.id),checked=>{value.modifierIds=value.modifierIds.filter(id=>id!==option.id);if(checked)value.modifierIds.push(option.id);});content.append(fieldset);}}
 }
 drawSelection();const quantity=menuInput(dialog,mt('setQuantity'),value.quantity,n=>{value.quantity=Number(n);},{type:'number',required:true});quantity.min='1';quantity.max='99';quantity.step='1';const error=menuNode('p','','menu-field-error');dialog.append(error);const footer=menuNode('div',undefined,'menu-inline');dialog.append(footer);
 menuButton(footer,t('cancel'),()=>POSDialogs.dismiss(dialog));menuButton(footer,mt('saveItem'),()=>{const invalid=[...dialog.querySelectorAll('input,select')].find(i=>!i.reportValidity());if(invalid)return;const child=candidates.find(i=>i.id===value.itemId);if(!child){error.textContent=mt('setInvalid');return;}if(child.pricingMode==='MATRIX'){const row=child.combinationPrices.find(r=>r.variantId===value.variantId&&r.optionIds.length===value.modifierIds.length&&r.optionIds.every(id=>value.modifierIds.includes(id)));if(row)value.combinationId=row.id;else delete value.combinationId;}else delete value.combinationId;
 const problem=menuSetComponentError(set,value);if(problem){error.textContent=problem;return;}const key=c=>JSON.stringify([c.itemId,c.variantId,[...c.modifierIds].sort()]),duplicate=set.components.find(c=>c!==existing&&key(c)===key(value));if(duplicate){if(duplicate.quantity+value.quantity>99){error.textContent=mt('setLimit');return;}duplicate.quantity+=value.quantity;if(existing)set.components=set.components.filter(c=>c!==existing);}else if(existing)Object.assign(existing,menuClone(value));else set.components.push(menuClone(value));set.kitchen=set.components.some(c=>menuState.items.find(i=>i.id===c.itemId)?.kitchen);menuMarkForm();dialog.close();menuDrawEditor();},'primary');
 POSDialogs.guard(dialog,()=>JSON.stringify(value)===original||confirmAction(mt('formDiscard')));document.body.append(dialog);dialog.onclose=()=>dialog.remove();dialog.showModal();
}
